diff:
--- a/src/export.rs
+++ b/src/export.rs
@@ -8,15 +8,29 @@ use crate::card::Card;

 const TEMPLATE: &str = "assets/card.tpl";

-pub async fn card_pdf(card: &Card) -> Result<Vec<u8>, ExportError> {
-    Err(ExportError::NotImplemented)
+pub async fn card_pdf(card: &Card) -> Result<Vec<u8>, ExportError> {
+    let template = std::fs::read_to_string(TEMPLATE)?;
+
+    let filled = template
+        .replace("{{name}}", &card.name)
+        .replace("{{owner}}", &card.owner);
+
+    let bytes = render(&filled).await?;
+
+    if bytes.is_empty() {
+        return Err(ExportError::EmptyRender);
+    }
+
+    Ok(bytes)
 }

 async fn render(html: &str) -> Result<Vec<u8>, ExportError> {
     renderer::html_to_pdf(html).await.map_err(ExportError::Render)
 }
